Cache<String, Product> cache = Caffeine.newBuilder()
    .maximumWeight(256 * 1024 * 1024) // bound BYTES, not entries: trade memory safety for hit ratio
    .weigher((String k, Product v) -> v.estimatedBytes())
    .expireAfterWrite(Duration.ofSeconds(60)) // bounds staleness, no cross-instance invalidation
    .recordStats() // hit ratio, eviction count: without these you are blind
    .build(key -> loadFromDb(key)); // read-through loader: centralises singleflight + error policy

// Negative caching: cache misses briefly so absent keys cannot crush the DB.
// Thundering herd: Caffeine coalesces concurrent loads on the same key;
// add TTL jitter per-key if a whole keyspace expires in lockstep.
